const ImageContentStarburstVersionGroupSchema = z
  .object({
    descriptorFloat: z
      .array(z.float32())
      .exactOptional()
      .openapi({ description: 'Raw dense float feature vector.' }),
    descriptorShort: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Short descriptor for image content features, e.g. compressed bytes. This is the compressed version of descriptor_float below. It can be can be decompressed to descriptor_float with a tiny bit of compression error (in most cases it should be totally fine).',
      }),
    enumVersion: z
      .enum([
        'UNKNOWN_VERSION',
        'STARBURST_V1',
        'STARBURST_V2',
        'STARBURST_V3',
        'STARBURST_V4',
        'STARBURST_VISUAL_V4',
        'STARBURST_V5',
        'STARBURST_V5_5',
      ])
      .exactOptional(),
    minorVersion: z
      .enum([
        'UNKNOWN_MINOR_VERSION',
        'V3_ORIGINAL',
        'V3_ENET_EMULATED',
        'V3_FNET_EMULATED',
        'V3_STARBURST_LITE',
        'V4_ORIGINAL',
        'V4_STRETCH_RESIZE',
        'VISUAL_V4_ORIGINAL',
        'V5_ORIGINAL',
        'V5_5_ORIGINAL',
      ])
      .exactOptional(),
    starburstTokens: z
      .array(z.int32())
      .exactOptional()
      .openapi({ description: 'Starburst tokens.' }),
    version: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          "The following integers are currently used: Starburst V1: 1 Starburst V2: 2 Starburst V3: 3 Starburst V4: 4 Starburst Visual V4: 1004 This field is deprecated. Please try to use the 'enum_version' in future.",
      }),
  })
  .openapi({ required: [] })
  .openapi('ImageContentStarburstVersionGroup')

