const PhotosVisionObjectrecGeoLocationSchema = z
  .object({
    altitudeMeters: z
      .float64()
      .exactOptional()
      .openapi({ description: "Altitude of the point above the earth's surface, in meters." }),
    countryCode: z.string().exactOptional().openapi({ description: 'Country code string.' }),
    fromGps: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Indicates if the lat/lon above is assumed to come from a GPS device.',
      }),
    lat: z
      .float64()
      .exactOptional()
      .openapi({
        description: 'Latitude in degrees north. Values south of the equator are negative.',
      }),
    latErrorBound: z
      .float64()
      .exactOptional()
      .openapi({
        description:
          'When applied to a single point, represents the estimated error bounds of manual geotagging. The estimate is based on size of the bounding box of the map used for manual geotagging. When applied to a group of points, the error bounds represent the dispersion around the group center (lat/lon above). The dispersion in this case is computed as half the interquartile range. Reference: http://en.wikipedia.org/wiki/Interquartile_range (lat +/- lat_error_bound, lng +/- lng_error_bound).',
      }),
    lon: z
      .float64()
      .exactOptional()
      .openapi({ description: 'Longitude in degrees east. Values west of 0 deg are negative.' }),
    lonErrorBound: z.float64().exactOptional(),
  })
  .openapi({
    description: 'The geo-location of a single point, or of the "center" of a group of points.',
    required: [],
  })
  .openapi('PhotosVisionObjectrecGeoLocation')

