const VideoAssetsVenomTransitionSchema = z
  .object({
    objective: z
      .enum([
        'OBJECTIVE_UNKNOWN',
        'OBJECTIVE_INGREDIENT_DO_ALL',
        'OBJECTIVE_INGREDIENT_GO_LIVE',
        'OBJECTIVE_INGREDIENT_VALIDATED',
        'OBJECTIVE_PRIMARY_ASSETS_DONE',
        'OBJECTIVE_PREVIEW_DONE',
        'OBJECTIVE_TRANSMUXED_DONE',
        'OBJECTIVE_MEDIA_INFO_DONE',
        'OBJECTIVE_PRIMARY_720P_TRANSCODES_DONE',
        'OBJECTIVE_PRIMARY_1080P_TRANSCODES_DONE',
        'OBJECTIVE_PRIMARY_2K_TRANSCODES_DONE',
        'OBJECTIVE_PRIMARY_4K_TRANSCODES_DONE',
        'OBJECTIVE_PRIMARY_8K_TRANSCODES_DONE',
        'OBJECTIVE_FINGERPRINTS_DONE',
        'OBJECTIVE_CHECKSUMS_DONE',
        'OBJECTIVE_CLAIM_DONE',
        'OBJECTIVE_THUMBNAILS_DONE',
        'OBJECTIVE_LIVE_STITCHABLE_ASSETS_DONE',
        'OBJECTIVE_CRAWL_ASSETS_DONE',
        'OBJECTIVE_VITAL_ASSETS_DONE',
        'OBJECTIVE_SAM_FEATURES_DONE',
        'OBJECTIVE_SPEECH_RECOGNITION_DONE',
        'OBJECTIVE_MULTI_TRACK_AUDIO_DONE',
      ])
      .exactOptional()
      .openapi({ description: 'The objective this transition is about. REQUIRED.' }),
    outcome: z
      .enum([
        'OUTCOME_UNKNOWN',
        'OUTCOME_SUCCESS',
        'OUTCOME_FAILED',
        'OUTCOME_INFEASIBLE',
        'OUTCOME_NOT_REQUESTED',
        'OUTCOME_PENDING',
      ])
      .exactOptional()
      .openapi({ description: 'Whether the objective is reached or not. REQUIRED.' }),
    reason: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'An optional debug string indicating the reason for this transition. This is typically omitted for OUTCOME_SUCCESS. e.g. "The video\'s content is invalid due to failed blobstore cloning."',
      }),
  })
  .openapi({
    description:
      'As video mutations are reconciled by Venom, we can tell if the ingredient did or did not reach certain objectives. When processing has completed, all objectives will have a corresponding transition. All transitions are reset for every mutation, but will take into account assets outside of that mutation. For example, if Asset X fails, and was part of "OBJECTIVE_PRIMARY_ASSETS_DONE", a rerun of Asset Y is destined to result in OUTCOME_FAILED, regardless of the fate of Asset Y. Some phenonema have effects on most or all Objectives. For example, a bad input file will result on OUTCOME_INFEASIBLE across the board (eventually, for now it\'s just GO_LIVE and DO_ALL, work in progress), and a failure to produce Format 18 will cause OUTCOME_FAILED across most Objectives.',
    required: [],
  })
  .openapi('VideoAssetsVenomTransition')

