const VideoVideoStreamInfoMetadataLutAttachmentsLut3DSchema = z
  .object({
    data: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "Lut data, sanitized and encoded in google's binary coded form of 3D look-up tables.",
      }),
    fileName: z
      .string()
      .exactOptional()
      .openapi({ description: 'Original file name of the lut (present in the original file)' }),
    size: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The size (in each dimension) of the lut. For a 3D cube of size NxNxN, this will be N. If the value is -1, then the file was determined to be invalid. This is useful for logging files where the input could not be parsed, and is useful for to indicate info of the 3D lut without having to decode/inspect the binary data.',
      }),
  })
  .openapi({ description: 'Description and encoding of a 3d lut.', required: [] })
  .openapi('VideoVideoStreamInfoMetadataLutAttachmentsLut3D')

const VideoVideoStreamInfoMetadataLutAttachmentsSchema = z
  .object({ lut: z.array(VideoVideoStreamInfoMetadataLutAttachmentsLut3DSchema).exactOptional() })
  .openapi({ description: 'An attached 3D look up table', required: [] })
  .openapi('VideoVideoStreamInfoMetadataLutAttachments')

const VideoFileFramePackingArrangementSchema = z
  .object({
    gridOffset0Horizontal: z.int32().exactOptional().openapi({ description: 'Grid positions' }),
    gridOffset0Vertical: z.int32().exactOptional(),
    gridOffset1Horizontal: z.int32().exactOptional(),
    gridOffset1Vertical: z.int32().exactOptional(),
    interpretation: z
      .enum(['FPA_INTERPRET_UNKNOWN', 'FPA_INTERPRET_LEFT_FIRST', 'FPA_INTERPRET_RIGHT_FIRST'])
      .exactOptional()
      .openapi({ description: 'Content interpretation' }),
    quincunxSampling: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Quincunx sampling flag indicating if quincunx sampling is used' }),
    type: z
      .enum([
        'FPA_NONE',
        'FPA_CHECKERBOARD',
        'FPA_COL_ALTERNATION',
        'FPA_ROW_ALTERNATION',
        'FPA_SIDE_BY_SIDE',
        'FPA_TOP_TO_BOTTOM',
        'FPA_FRAME_ALTERNATION',
      ])
      .exactOptional()
      .openapi({ description: 'Arrangement type' }),
  })
  .openapi({ description: 'Information on Frame Packing arrangement', required: [] })
  .openapi('VideoFileFramePackingArrangement')

const VideoVideoStreamInfoMetadataSchema = z
  .object({
    luts: VideoVideoStreamInfoMetadataLutAttachmentsSchema.exactOptional(),
    videoFpa: VideoFileFramePackingArrangementSchema.exactOptional().openapi({
      description: 'Information on Frame Packing arrangement',
    }),
  })
  .openapi({ required: [] })
  .openapi('VideoVideoStreamInfoMetadata')

