type CompositeDocExtraDupType = { ecnFp?: string; url?: string }

const CompositeDocExtraDupSchema: z.ZodType<CompositeDocExtraDupType> = z
  .object({
    ecnFp: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Fp96 of webmirror equivalence class as of last time this was exported.',
      }),
    url: z.string().exactOptional().openapi({ description: 'The url of the non-forwarding dup.' }),
  })
  .openapi({ description: 'The top non-forwarding dups of the canonical url.', required: [] })
  .openapi('CompositeDocExtraDup')

type CompositeDocForwardingDupType = {
  ecn?: string
  ecnFp?: string
  purposes?: number
  rawPagerank?: number
  repid?: string
  url?: string
  urlencoding?: number
}

const CompositeDocForwardingDupSchema: z.ZodType<CompositeDocForwardingDupType> = z
  .object({
    ecn: z
      .string()
      .exactOptional()
      .openapi({ description: "The name of the url's webmirror equivalence class." }),
    ecnFp: z.string().exactOptional(),
    purposes: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The purpose(s) of the forwarding dup indicating if it is used for forwarding signal/anchors generally, or only for forwarding some specific signal (e.g. navboost), or for some other purposes (e.g., not for forwarding any data but for making "info:" complete). See indexing/dups/public/dups.h for more details.',
      }),
    rawPagerank: z.int32().exactOptional().openapi({ description: 'Raw pagerank of the url.' }),
    repid: z
      .string()
      .exactOptional()
      .openapi({ description: 'The webmirror repid of the forwarding dup.' }),
    url: z.string().exactOptional().openapi({ description: 'The url of the forwarding dup.' }),
    urlencoding: z
      .int32()
      .exactOptional()
      .openapi({ description: 'The encoding of the url (see webutil/urlencoding for details).' }),
  })
  .openapi({
    description:
      'The top forwarding dups of the canonical url. (note: it may actually include some dups that are NOT used for forwarding data but for making "info:" complete)',
    required: [],
  })
  .openapi('CompositeDocForwardingDup')

