const QualityRankembedMustangMustangRankEmbedInfoSchema = z
  .object({
    compressedDocumentEmbedding:
      QualityRankembedMustangMustangRankEmbedInfoCompressedEmbeddingSchema.exactOptional().openapi({
        description: 'Each uint64 encodes 8 8-bit values for the quantized document embedding',
      }),
    fixedPointEncoding: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'This field replaces the above 3 "per-encoding-type-fields", where the encoding type (and the embedding type) are part of the encoding, and is stored in the first byte. The remaining bytes are the same as the previous 3 fields, but shifted by 1 byte. - byte[0]: encoding type & embedding type - byte[1....]: similar to the above depending on the encoding type.',
      }),
    scaledFixedPoint4Encoding: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '- byte[0]: version - bytes[1...4]: scalar - bytes[5,...]: the values, one byte per 2 values',
      }),
    scaledFixedPoint8Encoding: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '- byte[0]: version - bytes[1...4]: scalar - bytes[5,...]: the values, one byte per value',
      }),
    scaledShiftedFixedPoint4Encoding: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '- byte[0]: version - bytes[1...4]: scalar - bytes[5...8]: shift - bytes[9,...]: the values, one byte per 2 values',
      }),
    versionAndImprovInfo: z
      .uint32()
      .exactOptional()
      .openapi({
        description:
          'First 7 bits encode the version, then each chunck of 5 bits encode the index of a potential improv query (lsb to msb) -------|-----|-----|-----|-----|----- version| id1 | id2 | id3 | id4 | id5 where id1 is the index of the first improv query in the improv debug table. As of cl/270008220, this field only contains the version info. For backward compatibility, version still only uses the first 7 bits, and is still prepended by 5 1 bits.',
      }),
  })
  .openapi({
    description:
      'Used as Mustang attachment DO NOT: - ACCESS THE PROTO FIELDS DIRECTLY - USE THE DECODING LIBRARY IN quality/rankembed/mustang/fixed_point_decoding_helpers.h INSTEAD. - USE HARDCODED MustangRankEmbedInfo TEXT PROTOS IN TESTS! USE quality/rankembed/test_utils/mustang_rankembed_info_utils.h INSTEAD.',
    required: [],
  })
  .openapi('QualityRankembedMustangMustangRankEmbedInfo')

