        'PER_MINUTE',
        'PER_HOUR',
        'PER_DAY',
        'PER_NIGHT',
        'PER_WEEK',
        'PER_MONTH',
        'PER_YEAR',
        'PER_VOLUME_UNIT',
        'PER_LITER',
        'PER_GLASS',
        'PER_BOTTLE',
        'PER_POT',
        'PER_LENGTH_UNIT',
        'PER_CENTIMETER',
        'PER_METER',
        'PER_KILOMETER',
        'PER_MASS_UNIT',
        'PER_GRAM',
        'PER_KILOGRAM',
        'PER_OUNCE',
        'PER_POUND',
