const NlpSemanticParsingModelsCommunicationRecipientSchema = z
  .object({
    calendarEvent: AssistantApiCoreTypesCalendarEventSchema.exactOptional(),
    calendarEventWrapper: AssistantApiCoreTypesCalendarEventWrapperSchema.exactOptional(),
    contact: NlpSemanticParsingModelsPersonPersonSchema.exactOptional().openapi({
      description: "Contact details (e.g. gaia_id, phone, etc). Replaces 'focus_name' above.",
    }),
    evalData: NlpSemanticParsingAnnotationEvalDataSchema.exactOptional().openapi({
      description:
        'Required, but should only be used inside Aqua and must not be used by outside clients!!',
    }),
    isAnnotatedFromText: z.boolean().exactOptional(),
    nameAnnotationSource: z
      .enum([
        'UNKNOWN_NAME_ANNOTATOR',
        'FOCUS_NAME',
        'DEVICE_CONTACT',
        'SAFT_PERSON',
        'NAME_DETECTION_PERSON',
        'NAME_PERSON',
        'MANUAL_RULES',
        'SAFT_POS',
        'TEXT',
      ])
      .exactOptional()
      .openapi({ description: 'Deprecated in favor of recipient.contact.name_annotation_source.' }),
    numberAnnotationSource: z
      .enum(['UNKNOWN_NUMBER_ANNOTATOR', 'PHONE_NUMBER_ANNOTATOR', 'NUMBER_ANNOTATOR', 'MANUAL'])
      .exactOptional(),
    rawText: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'NOTE: for CONTACT recipient, this is *NOT* the real raw text of the recipient span of historical reasons. Major differences includes: - stripping possessive suffix, e.g. "John\'s" -> "John" - stripping prefix/suffix/title, e.g. "Mr. John" -> "John" - uninflect name for languages like Russian, e.g. "Андрею" -> "Андрей" Currently this is the same as .contact.name, and is used as the string shown to the user on clientside UI. If you\'re looking for real raw text, use .contact.raw_text',
      }),
    recipientType: z
      .enum([
        'CONTACT',
        'BUSINESS',
        'EMAIL_ADDRESS',
        'PHONE_NUMBER',
        'AMBIGUOUS',
        'CALENDAR_EVENT',
        'CALENDAR_EVENT_WRAPPER',
      ])
      .exactOptional(),
    relationship:
      NlpSemanticParsingModelsCommunicationRelationshipArgumentSchema.exactOptional().openapi({
        description: 'A reference to a person by relationship name. eg. my father.',
      }),
    sensitiveNumBytes: z.int32().exactOptional(),
    sensitiveStartByte: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The beginning and end of the recipient name that should be removed before logging.',
      }),
  })
  .openapi({
    description:
      'It can be a contact (person name), a business name, an email address or a phone number. NOTE: Unfortunately the name of this message is not generic enough. Contact would be a better name.',
    required: [],
  })
  .openapi('NlpSemanticParsingModelsCommunicationRecipient')

