const VendingConsumerProtoTrustedGenomePolicyTargetRegionSchema = z
  .object({
    localizedRegion: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Localized name for targeted regions. e.g. San Francisco Bay Area Required.',
      }),
    mid: z
      .string()
      .exactOptional()
      .openapi({ description: 'Associated KG entity mid for region. e.g. /m/06pvr' }),
  })
  .openapi({ required: [] })
  .openapi('VendingConsumerProtoTrustedGenomePolicyTargetRegion')

const VendingConsumerProtoTrustedGenomePolicySchema = z
  .object({
    localizedRegionOverride: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Override text for region for special treatment. Override will be used in special cases for example regions are too long to show in UI, the override will be "CA/NV/..." to cut it short. By keeping a region override string we\'ll have more flexibility to adjust what we show on UI. Optional.',
      }),
    policyType: z
      .array(
        z.enum([
          'UNKNOWN_POLICY_TYPE',
          'GOVERNMENT_COMMISSIONED',
          'APOLLO_APPROVED',
          'APOLLO_EXPRESS',
        ]),
      )
      .exactOptional()
      .openapi({ description: 'Policy type. e.g. Government Endorsed, Apollo Required.' }),
    targetRegion: z
      .array(VendingConsumerProtoTrustedGenomePolicyTargetRegionSchema)
      .exactOptional()
      .openapi({ description: 'Contains target region for the current policy. Optional' }),
  })
  .openapi({ description: 'Proto message containing policy related information.', required: [] })
  .openapi('VendingConsumerProtoTrustedGenomePolicy')

const VendingConsumerProtoTrustedGenomeEntitySchema = z
  .object({
    categoryId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The category id matching this trusted genome entity. e.g. Action tag with id /m/025zzc matches category of id GAME_ACTION',
      }),
    id: z
      .string()
      .exactOptional()
      .openapi({ description: 'The identifier of a play trusted genome entity. Required.' }),
    level: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The level of the entity. E.g. in hierarchy like Action -> Platformer > Endless Runner. Action is level 1, Platformer is level 2 and Endless Runner is level 3. Currently, only APP_TAXONOMY and GAME_TAXONOMY type may have the levels. For entity that does not have hierarchy, its level is 1. Required.',
      }),
    predicateName: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The name of the relation between the app and the entity. Required.',
      }),
    queryText: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The localized query string for this trusted genome entity. This query will be used when we want to bring users to SERP on click.',
      }),
    score: z
      .float32()
      .exactOptional()
      .openapi({ description: 'The confidence score of the entity to the app.' }),
    title: z.string().exactOptional().openapi({ description: 'The localized title. Required.' }),
    userVisible: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'This boolean is used to decide whether this entity will be shown on user-facing features in the Store or not.',
      }),
  })
  .openapi({
    description:
      'Proto message containing the id, localized title, score, and hierarchy level of a trusted genome entity. Next ID: 10',
    required: [],
  })
  .openapi('VendingConsumerProtoTrustedGenomeEntity')

const VendingConsumerProtoTrustedGenomeHierarchySchema = z
  .object({
    entity: z
      .array(VendingConsumerProtoTrustedGenomeEntitySchema)
      .exactOptional()
      .openapi({
        description:
          'List of entities (one or multiple) that belong in the same hierarchy. The entries will be ordered such that the first entry will be of level 1, and the second entry will be of level 2, and so on. Required',
      }),
    hierarchyType: z
      .enum(['UNKNOWN_HIERARCHY_TYPE', 'GD2_GAME_MAIN', 'GD2_GAME_SUB'])
      .exactOptional()
      .openapi({
        description:
          "The (hierarchy-level) type of this Trusted Genome hierarchy. Will only be populated when meeting certain criteria, e.g. 'GD2_Game_Main' means this hierarchy of entities can serve as the main game genre for Game Discovery 2.0.",
      }),
    source: z
      .enum([
        'UNKNOWN_TRUSTED_GENOME_SOURCE',
        'TRUSTED_GENOME_2',
        'VALIDATED_DEVELOPER',
        'DEVELOPER_PROVIDED',
      ])
      .exactOptional()
      .openapi({ description: 'The source of this Trusted Genome hierarchy.' }),
    trustedGenomeType: z
      .enum([
        'UNKNOWN_ENTITY_TYPE',
        'APP_TAXONOMY',
        'APP_ATTRIBUTE',
        'GAME_TAXONOMY',
        'GAMEPLAY_ELEMENT',
        'GAMEPLAY_MODE',
        'GAME_GRAPHIC_STYLE',
        'GAME_THEME_SETTING',
        'GAME_CONNECTIVITY',
        'GAME_DIMENSIONAL_PLANES',
        'GAME_MONETIZATION',
        'ACCESSIBLITY',
        'ASSISTANT',
        'CHROMEBOOK_COMPATIBILITY',
      ])
      .exactOptional()
      .openapi({
        description:
          'The (entity-level) type of trusted genome entities in this hierarchy. Required.',
      }),
  })
  .openapi({
    description:
      'Proto message containing one or multiple trusted genome entity. This is used to capture entities that belong to the same type and have parent-children relationship in the taxonomy. e.g. One hierarchy may include 3 entities with Game_Taxonomy Type: (1) Action (Level 1) (2) Platformer (Level 2 under Action) (3) Endless Runner (Level 3 under Platformer) e.g. One hierarchy may also include only 1 entity with Game_Graphic_Style: (1) Anime (No level information) Next ID: 5',
    required: [],
  })
  .openapi('VendingConsumerProtoTrustedGenomeHierarchy')

