const RepositoryWebrefEntityNameScoreSchema: z.ZodType<RepositoryWebrefEntityNameScoreType> = z
  .lazy(() =>
    z
      .object({
        bootstrappingPreviousIteration:
          RepositoryWebrefBootstrappingScoreSchema.exactOptional().openapi({
            description:
              'If the EntityNameScore is part of a bootstrapped model, then this field contains the score_ratio from the previous model ("Model 0"). If Model 0 does not have a corresponding entry, because it did not know about this name for this entity, then bootstrapping_previous_iteration is left empty.',
          }),
        confidence: z
          .float32()
          .exactOptional()
          .openapi({
            description:
              'Confidence that this name is a trusted name of the entity. A reasonable threshold for name trust is 0.6. A name can be trusted and still have very low score_ratio, esp. if it is ambiguous (e.g. \'mercury\') and/or not the dominant interpretation (e.g. "siberian husky" -> /m/06krnsr (a book)).',
          }),
        debugInfo: z
          .array(RepositoryWebrefEntityDebugInfoSchema)
          .exactOptional()
          .openapi({ description: 'Debug information about the entity.' }),
        debugVariantSignals: z
          .array(RepositoryWebrefPreprocessingNameVariantSignalsSchema)
          .exactOptional()
          .openapi({
            description: 'Source and score data, this is internal to refx (e.g. for demo/debug).',
          }),
        entity: RepositoryWebrefEntityJoinSchema.exactOptional().openapi({
          description:
            'Sparse metadata about the entity, usage should be moved back to individual fields, this avoids having cyclic dependencies.',
        }),
        extendedScoreRatio: z
          .array(RepositoryWebrefExtendedEntityNameScoreSchema)
          .exactOptional()
          .openapi({
            description:
              'Stores region specific score ratios for the entity when it is significantly different from the language version above.',
          }),
        includeInModel: z
          .boolean()
          .exactOptional()
          .openapi({ description: 'Include this name in the name lookup table.' }),
        internalBootstrapIsOpenWorld: z
          .boolean()
          .exactOptional()
          .openapi({ description: 'Transient field, only used in bootstrap pipeline.' }),
        internalIsClusterParent: z.boolean().exactOptional(),
        isClusterGlobal: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              "Set to true iff the concept is cluster parent and the name can be a name for any child of the cluster. (e.g. 'starbucks' is cluster_global for the [Starbucks] chain cluster).",
          }),
        isDropped: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Documened at: repository/webref/universal/webref_data/enricher/entity-data.h',
          }),
        isMatchlessResultContext: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Only for context names: Whether this EntityNameScore represents an entity that was dominant in the search results but was not annotated by QRef during learning. Matchless result contexts are useful for bootstrapping, where different model iterations may have different names and thus context scores from Model 0 that are inconsistent with the names from Model 1.',
          }),
        isPruned: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Documened at: repository/webref/universal/webref_data/enricher/entity-data.h',
          }),
        mid: z.string().exactOptional().openapi({ description: 'The id of the entity.' }),
        nameMetadata: RepositoryWebrefPreprocessingNameEntityMetadataSchema.exactOptional().openapi(
          { description: 'Metadata about this name aggregated from name signals.' },
        ),
        rangeMetadata: z
          .array(RepositoryWebrefRangeMetadataSchema)
          .exactOptional()
          .openapi({
            description: 'Metadata of segment range, which is annotated by this entity.',
          }),
        score: z
          .float32()
          .exactOptional()
          .openapi({
            description:
              'The absolute score of that entity. score = artificial_score + volume_based_score',
          }),
        scoreRatio: z
          .float32()
          .exactOptional()
          .openapi({
            description:
              'Ratio between this entity score and the total score over all entities. This is including the "open world" information if it was estimated.',
          }),
        useAsNameCandidate: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              "When this field is true, we consider this context name as candidate in Enricher's names pipeline.",
          }),
        volumeBasedScore: z
          .float32()
          .exactOptional()
          .openapi({
            description:
              'Absolute score that comes from quantitative sources such as navboost clicks, anchors, etc. artificial_score = score - volume_based_score',
          }),
      })
      .openapi({
        description: 'Represents a score for an entity. Next available tag: 39.',
        required: [],
      }),
  )
  .openapi('RepositoryWebrefEntityNameScore')

